#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int parent[10];
int rank[10];

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void union_set(int x, int y) {
    int root_x = find(x);
    int root_y = find(y);

    if (root_x != root_y) {
        if (rank[root_x] < rank[root_y]) {
            parent[root_x] = root_y;
        } else if (rank[root_x] > rank[root_y]) {
            parent[root_y] = root_x;
        } else {
            parent[root_y] = root_x;
            rank[root_x];
        }
    }
}

int main(int argc, char **argv) {
    for (int i = 0; i < 10; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "U") == 0) {
            int x = atoi(argv[i + 1]);
            int y = atoi(argv[i + 2]);
            union_set(x, y);
            printf("UNION %d %d\n", x, y);
            i += 2;
        } else if (strcmp(argv[i], "F") == 0) {
            int x = atoi(argv[i + 1]);
            int root = find(x);
            printf("FIND %d=%d\n", x, root);
            i += 1;
        }
    }

    return 0;
}
